### 4.2 並列処理
```typescript
import { Worker } from 'worker_threads';
import pLimit from 'p-limit';

export class ParallelTool {
  /**
   * 並列処理をサポートするツール
   */
  private limit: pLimit.Limit;

  constructor() {
    // 同時実行数を制限
    this.limit = pLimit(4);
  }

  /**
   * 複数アイテムの並列処理
   */
  async executeParallel(
    items: ToolInput[],
  ): Promise<Result<ToolOutput, ToolError>[]> {
    // I/Oバウンドなタスク
    if (this.isIoBound()) {
      const promises = items.map((item) =>
        this.limit(() => this.processAsync(item)),
      );
      return Promise.all(promises);
    }

    // CPUバウンドなタスク（Worker Threads使用）
    const workers = await Promise.all(
      items.map((item) => this.processWithWorker(item)),
    );
    return workers;
  }

  private isIoBound(): boolean {
    // I/Oバウンドかどうかの判定ロジック
    return true;
  }

  private async processAsync(
    input: ToolInput,
  ): Promise<Result<ToolOutput, ToolError>> {
    // 非同期処理
    return ok({ result: 'processed', metadata: {} });
  }

  private async processWithWorker(
    input: ToolInput,
  ): Promise<Result<ToolOutput, ToolError>> {
    return new Promise((resolve) => {
      const worker = new Worker('./worker.js', {
        workerData: { input },
      });

      worker.on('message', (result) => {
        resolve(ok(result));
      });

      worker.on('error', (error) => {
        resolve(
          err({
            code: 'WORKER_ERROR',
            message: error.message,
            toolName: 'ParallelTool',
            recoverable: false,
          }),
        );
      });
    });
  }
}

